package com.tcgsessionoverlay;

import com.tcgsessionoverlay.overlay.NumberStyle;
import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.ui.overlay.components.ComponentConstants;

@ConfigGroup("tcgsessionoverlay")
public interface TcgSessionOverlayConfig extends Config
{
	@ConfigSection(
		name = "Appearance",
		description = "How the overlay looks.",
		position = 80
	)
	String appearanceSection = "appearance";

	@ConfigItem(
		keyName = "showCredits",
		name = "Show credits",
		description = "Show the credits earned this session.",
		position = 1
	)
	default boolean showCredits()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showRates",
		name = "Show rates",
		description = "Show credits earned per hour. Time spent with no XP for over five minutes is not counted.",
		position = 2
	)
	default boolean showRates()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showXpCountdown",
		name = "Show XP countdown",
		description = "Show progress to the next credit award for the skill you are training.",
		position = 3
	)
	default boolean showXpCountdown()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight",
		description = "Colour used once you have earned credits this session.",
		position = 81,
		section = appearanceSection
	)
	default Color highlightColor()
	{
		return Color.GREEN;
	}

	@ConfigItem(
		keyName = "hideWhenIdle",
		name = "Hide when idle",
		description = "Hide the overlay after five minutes with no XP. It returns on your next XP drop.",
		position = 82,
		section = appearanceSection
	)
	default boolean hideWhenIdle()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "backgroundColor",
		name = "Background",
		description = "Overlay background colour. Drag the alpha slider left to make the panel more transparent.",
		position = 83,
		section = appearanceSection
	)
	default Color backgroundColor()
	{
		return ComponentConstants.STANDARD_BACKGROUND_COLOR;
	}

	@ConfigItem(
		keyName = "numberStyle",
		name = "Number format",
		description = "Full shows 199,982. Short shows 199.9K.",
		position = 84,
		section = appearanceSection
	)
	default NumberStyle numberStyle()
	{
		return NumberStyle.FULL;
	}
}

package com.tcgsessionoverlay;

import com.google.inject.Provides;
import com.tcgsessionoverlay.interop.TcgStateReader;
import com.tcgsessionoverlay.overlay.TcgSessionOverlay;
import com.tcgsessionoverlay.session.CreditsTracker;
import com.tcgsessionoverlay.session.SessionClock;
import com.tcgsessionoverlay.session.XpCountdownTracker;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "TCG Session Overlay"
)
public class TcgSessionOverlayPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private TcgSessionOverlayConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TcgSessionOverlay overlay;

	@Inject
	private EventBus eventBus;

	@Inject
	private XpCountdownTracker xpCountdownTracker;

	@Inject
	private TcgStateReader tcgStateReader;

	@Inject
	private CreditsTracker creditsTracker;

	@Inject
	private SessionClock sessionClock;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
		eventBus.register(xpCountdownTracker);
		eventBus.register(tcgStateReader);
		eventBus.register(creditsTracker);
		eventBus.register(sessionClock);
		log.debug("TCG Session Overlay started");
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		eventBus.unregister(xpCountdownTracker);
		eventBus.unregister(tcgStateReader);
		eventBus.unregister(creditsTracker);
		eventBus.unregister(sessionClock);
		log.debug("TCG Session Overlay stopped");
	}

	@Provides
	TcgSessionOverlayConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TcgSessionOverlayConfig.class);
	}
}

package com.tcgsessionoverlay.interop;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import lombok.Getter;
import net.runelite.api.Skill;

@Getter
public final class TcgState
{
	private final long profileSavedAtUnix;
	private final Map<Skill, Long> uncreditedXpBySkill;
	private final Map<Skill, Long> baselineSkillXp;

	public TcgState(
		long profileSavedAtUnix,
		Map<Skill, Long> uncreditedXpBySkill,
		Map<Skill, Long> baselineSkillXp)
	{
		this.profileSavedAtUnix = profileSavedAtUnix;
		this.uncreditedXpBySkill = copyOf(uncreditedXpBySkill);
		this.baselineSkillXp = copyOf(baselineSkillXp);
	}

	public long getUncreditedXp(Skill skill)
	{
		return uncreditedXpBySkill.getOrDefault(skill, 0L);
	}

	public boolean hasBaselineXp(Skill skill)
	{
		return baselineSkillXp.containsKey(skill);
	}

	public long getBaselineXp(Skill skill)
	{
		return baselineSkillXp.getOrDefault(skill, 0L);
	}

	private static Map<Skill, Long> copyOf(Map<Skill, Long> source)
	{
		Map<Skill, Long> copy = new EnumMap<>(Skill.class);
		copy.putAll(source);
		return Collections.unmodifiableMap(copy);
	}
}

package com.tcgsessionoverlay.interop;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Optional;
import java.util.zip.GZIPInputStream;
import lombok.extern.slf4j.Slf4j;

// Reimplements osrs-tcg's own storage format, not imported, so there is no compile time link.
// The encoding is fixed and public, nothing secret is being reverse engineered.
@Slf4j
public final class TcgStateDecoder
{
	private static final String VERSION_PREFIX_V3 = "RLTCG_v3:";
	private static final String VERSION_PREFIX_V2 = "RLTCG_v2:";
	private static final byte[] SALT = "RLTCG|osrs-tcg!".getBytes(StandardCharsets.US_ASCII);

	private TcgStateDecoder()
	{
	}

	public static Optional<String> decode(String raw)
	{
		if (raw == null)
		{
			return Optional.empty();
		}

		try
		{
			if (raw.startsWith(VERSION_PREFIX_V3))
			{
				byte[] decoded = Base64.getDecoder().decode(raw.substring(VERSION_PREFIX_V3.length()));
				return Optional.of(new String(gunzip(decoded), StandardCharsets.UTF_8));
			}

			if (raw.startsWith(VERSION_PREFIX_V2))
			{
				byte[] decoded = Base64.getDecoder().decode(raw.substring(VERSION_PREFIX_V2.length()));
				byte[] xored = xor(decoded);
				return Optional.of(new String(gunzip(xored), StandardCharsets.UTF_8));
			}

			return Optional.empty();
		}
		catch (Exception e)
		{
			log.debug("Failed to decode osrs-tcg state", e);
			return Optional.empty();
		}
	}

	private static byte[] xor(byte[] data)
	{
		byte[] result = new byte[data.length];
		for (int i = 0; i < data.length; i++)
		{
			result[i] = (byte) (data[i] ^ SALT[i % SALT.length]);
		}
		return result;
	}

	private static byte[] gunzip(byte[] data) throws Exception
	{
		try (GZIPInputStream gzipInputStream = new GZIPInputStream(new ByteArrayInputStream(data));
			ByteArrayOutputStream output = new ByteArrayOutputStream())
		{
			byte[] buffer = new byte[4096];
			int read;
			while ((read = gzipInputStream.read(buffer)) != -1)
			{
				output.write(buffer, 0, read);
			}
			return output.toByteArray();
		}
	}
}

package com.tcgsessionoverlay.interop;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

@Slf4j
@Singleton
public class TcgStateParser
{
	private static final Map<String, Skill> SKILLS_BY_NAME = skillsByName();

	private final Gson gson;

	@Inject
	public TcgStateParser(Gson gson)
	{
		this.gson = gson;
	}

	public Optional<TcgState> parse(String json)
	{
		if (json == null || json.isEmpty())
		{
			return Optional.empty();
		}

		try
		{
			JsonObject root = gson.fromJson(json, JsonObject.class);
			if (root == null)
			{
				return Optional.empty();
			}

			return Optional.of(new TcgState(
				readLong(root, "profileSavedAtUnix"),
				parseSkillMap(root, "uncreditedXpBySkill"),
				parseSkillMap(root, "skillXp")));
		}
		catch (Exception e)
		{
			log.debug("Failed to parse osrs-tcg state", e);
			return Optional.empty();
		}
	}

	private static Map<Skill, Long> parseSkillMap(JsonObject root, String key)
	{
		Map<Skill, Long> bySkill = new EnumMap<>(Skill.class);
		JsonElement baselineElement = root.get("skillCreditBaseline");
		if (baselineElement == null || !baselineElement.isJsonObject())
		{
			return bySkill;
		}

		JsonElement mapElement = baselineElement.getAsJsonObject().get(key);
		if (mapElement == null || !mapElement.isJsonObject())
		{
			return bySkill;
		}

		for (Map.Entry<String, JsonElement> entry : mapElement.getAsJsonObject().entrySet())
		{
			Skill skill = SKILLS_BY_NAME.get(entry.getKey());
			if (skill == null || !entry.getValue().isJsonPrimitive())
			{
				continue;
			}

			bySkill.put(skill, entry.getValue().getAsLong());
		}

		return bySkill;
	}

	private static long readLong(JsonObject object, String key)
	{
		JsonElement element = object.get(key);
		return element != null && element.isJsonPrimitive() ? element.getAsLong() : 0L;
	}

	private static Map<String, Skill> skillsByName()
	{
		Map<String, Skill> byName = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			byName.put(skill.getName(), skill);
		}
		return byName;
	}
}

package com.tcgsessionoverlay.interop;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.FileTime;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Duration;
import java.time.Instant;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.client.RuneLite;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

@Slf4j
@Singleton
public class TcgStateReader
{
	private static final String SAVE_FILE_NAME = "tcg.save";
	private static final Duration CHECK_INTERVAL = Duration.ofSeconds(5);

	private final Client client;
	private final TcgStateParser parser;

	private Optional<TcgState> cachedState = Optional.empty();
	private Instant lastCheckedAt = Instant.MIN;
	private FileTime lastModified;

	@Inject
	public TcgStateReader(Client client, TcgStateParser parser)
	{
		this.client = client;
		this.parser = parser;
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		cachedState = Optional.empty();
		lastCheckedAt = Instant.MIN;
		lastModified = null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		getState();
	}

	public Optional<TcgState> getState()
	{
		Instant now = Instant.now();
		if (Duration.between(lastCheckedAt, now).compareTo(CHECK_INTERVAL) < 0)
		{
			return cachedState;
		}

		lastCheckedAt = now;
		refreshIfChanged();
		return cachedState;
	}

	private void refreshIfChanged()
	{
		Path saveFile = resolveSaveFile();
		if (saveFile == null || !Files.isRegularFile(saveFile))
		{
			cachedState = Optional.empty();
			lastModified = null;
			return;
		}

		try
		{
			FileTime modified = Files.getLastModifiedTime(saveFile);
			if (modified.equals(lastModified))
			{
				return;
			}

			lastModified = modified;
			cachedState = readAndParse(saveFile);
		}
		catch (IOException e)
		{
			log.debug("Failed to check osrs-tcg save file", e);
		}
	}

	private Optional<TcgState> readAndParse(Path saveFile)
	{
		try
		{
			String raw = Files.readString(saveFile, StandardCharsets.UTF_8);
			Optional<TcgState> parsed = TcgStateDecoder.decode(raw).flatMap(parser::parse);
			parsed.ifPresent(state -> log.debug("Read osrs-tcg state: savedAt={}", state.getProfileSavedAtUnix()));
			return parsed;
		}
		catch (IOException e)
		{
			log.debug("Failed to read osrs-tcg save file", e);
			return Optional.empty();
		}
	}

	private Path resolveSaveFile()
	{
		long accountHash = client.getAccountHash();
		if (accountHash == -1L)
		{
			return null;
		}

		String accountDirName = sha256Hex(Long.toString(accountHash));
		return Path.of(RuneLite.RUNELITE_DIR.getAbsolutePath(), "OSRS-TCG", "profiles", accountDirName, SAVE_FILE_NAME);
	}

	private static String sha256Hex(String value)
	{
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] hash = digest.digest(value.getBytes(StandardCharsets.UTF_8));
			StringBuilder builder = new StringBuilder(hash.length * 2);
			for (byte b : hash)
			{
				builder.append(String.format("%02x", b));
			}
			return builder.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException("SHA-256 not available", e);
		}
	}
}

package com.tcgsessionoverlay.overlay;

import net.runelite.client.util.QuantityFormatter;

public enum NumberStyle
{
	FULL("Full"),
	SHORT("Short");

	private final String label;

	NumberStyle(String label)
	{
		this.label = label;
	}

	public String format(long value)
	{
		return this == SHORT ? QuantityFormatter.quantityToStackSize(value) : QuantityFormatter.formatNumber(value);
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.tcgsessionoverlay.overlay;

import com.tcgsessionoverlay.TcgSessionOverlayConfig;
import com.tcgsessionoverlay.session.CreditsTracker;
import com.tcgsessionoverlay.session.RatesTracker;
import com.tcgsessionoverlay.session.SessionClock;
import com.tcgsessionoverlay.session.XpCountdownTracker;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import javax.inject.Inject;
import net.runelite.api.Skill;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class TcgSessionOverlay extends OverlayPanel
{
	private static final Color SECTION_COLOR = Color.ORANGE;
	private static final int MINIMUM_PANEL_WIDTH = 160;

	private final TcgSessionOverlayConfig config;
	private final CreditsTracker creditsTracker;
	private final RatesTracker ratesTracker;
	private final SessionClock sessionClock;
	private final XpCountdownTracker xpCountdownTracker;

	private FontMetrics fontMetrics;
	private int requiredContentWidth;

	@Inject
	private TcgSessionOverlay(
		TcgSessionOverlayConfig config,
		CreditsTracker creditsTracker,
		RatesTracker ratesTracker,
		SessionClock sessionClock,
		XpCountdownTracker xpCountdownTracker)
	{
		this.config = config;
		this.creditsTracker = creditsTracker;
		this.ratesTracker = ratesTracker;
		this.sessionClock = sessionClock;
		this.xpCountdownTracker = xpCountdownTracker;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setGap(new Point(0, 4));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (config.hideWhenIdle() && sessionClock.isIdle())
		{
			return null;
		}

		fontMetrics = graphics.getFontMetrics();
		requiredContentWidth = 0;

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("TCG Session")
			.color(SECTION_COLOR)
			.build());

		renderCredits();
		renderRates();
		renderXpCountdown();

		panelComponent.setPreferredSize(new Dimension(panelWidth(), 0));
		setPreferredColor(config.backgroundColor());

		return super.render(graphics);
	}

	private void renderCredits()
	{
		if (!config.showCredits())
		{
			return;
		}

		addSection("Credits");

		if (!creditsTracker.hasState())
		{
			addWaiting("Waiting for TCG data");
			return;
		}

		long sessionCredits = creditsTracker.getSessionCreditsEarned();
		addLine("This session", "+" + format(sessionCredits), highlightWhen(sessionCredits > 0));
	}

	private void renderRates()
	{
		if (!config.showRates())
		{
			return;
		}

		addSection("Rates");

		long creditsPerHour = ratesTracker.getCreditsPerHour();
		addLine("Credits / hr", creditsPerHour >= 0 ? format(creditsPerHour) : "-");
	}

	private void renderXpCountdown()
	{
		if (!config.showXpCountdown())
		{
			return;
		}

		addSection("XP Countdown");

		Skill trackedSkill = xpCountdownTracker.getTrackedSkill();
		if (trackedSkill == null)
		{
			addWaiting("Waiting for XP");
			return;
		}

		addSkillName(trackedSkill.getName());

		if (!xpCountdownTracker.isTrackedSkillEarningCredits())
		{
			addLine("Level up credits", format(xpCountdownTracker.getNextLevelCredits()));
			return;
		}

		ProgressBarComponent progressBar = new ProgressBarComponent();
		progressBar.setMaximum(xpCountdownTracker.getBlockSize());
		progressBar.setValue(xpCountdownTracker.getXpInCurrentBlock());
		progressBar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.FULL);
		panelComponent.getChildren().add(progressBar);

		int actionsRemaining = xpCountdownTracker.getActionsRemaining();
		addLine("Actions left", actionsRemaining >= 0 ? String.valueOf(actionsRemaining) : "-");

		int medianXpPerAction = xpCountdownTracker.getMedianXpPerAction();
		if (medianXpPerAction > 0)
		{
			addLine("Xp per action", String.valueOf(medianXpPerAction));
		}
	}

	private void addWaiting(String message)
	{
		widen(message, "");
		panelComponent.getChildren().add(LineComponent.builder()
			.left(message)
			.leftColor(Color.LIGHT_GRAY)
			.build());
	}

	private void addSkillName(String name)
	{
		widen(name, "");
		panelComponent.getChildren().add(LineComponent.builder()
			.left(name)
			.build());
	}

	private int panelWidth()
	{
		return Math.max(MINIMUM_PANEL_WIDTH, requiredContentWidth + 2 * ComponentConstants.STANDARD_BORDER);
	}

	private void addSection(String name)
	{
		widen(name, "");
		panelComponent.getChildren().add(LineComponent.builder()
			.left(name)
			.leftColor(SECTION_COLOR)
			.build());
	}

	private Color highlightWhen(boolean condition)
	{
		return condition ? config.highlightColor() : Color.WHITE;
	}

	private void addLine(String label, String value)
	{
		addLine(label, value, Color.WHITE);
	}

	private void addLine(String label, String value, Color valueColor)
	{
		widen(label, value);
		panelComponent.getChildren().add(LineComponent.builder()
			.left(label)
			.right(value)
			.rightColor(valueColor)
			.build());
	}

	private void widen(String left, String right)
	{
		requiredContentWidth = Math.max(requiredContentWidth,
			fontMetrics.stringWidth(left) + fontMetrics.stringWidth(right));
	}

	private String format(long value)
	{
		return config.numberStyle().format(value);
	}
}

package com.tcgsessionoverlay.session;

import java.util.EnumSet;
import java.util.Set;
import lombok.Getter;
import net.runelite.api.Skill;

@Getter
public enum CreditRule
{
	NONE(0, 0),
	STANDARD(1000, 100),
	SLAYER(100, 10);

	private static final Set<Skill> WITHOUT_XP_CREDITS = EnumSet.of(
		Skill.ATTACK,
		Skill.DEFENCE,
		Skill.STRENGTH,
		Skill.MAGIC,
		Skill.RANGED,
		Skill.HITPOINTS);

	private final int xpPerBlock;
	private final int creditsPerBlock;

	CreditRule(int xpPerBlock, int creditsPerBlock)
	{
		this.xpPerBlock = xpPerBlock;
		this.creditsPerBlock = creditsPerBlock;
	}

	public static CreditRule forSkill(Skill skill)
	{
		if (skill == null || WITHOUT_XP_CREDITS.contains(skill))
		{
			return NONE;
		}

		return skill == Skill.SLAYER ? SLAYER : STANDARD;
	}

	public boolean earnsCredits()
	{
		return this != NONE;
	}
}

package com.tcgsessionoverlay.session;

import com.tcgsessionoverlay.interop.TcgState;
import com.tcgsessionoverlay.interop.TcgStateReader;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

@Singleton
public class CreditsTracker
{
	private final Client client;
	private final TcgStateReader tcgStateReader;
	private final Map<Skill, Long> sessionCarryBySkill = new EnumMap<>(Skill.class);
	private final Map<Skill, Long> sessionSkillXpBySkill = new EnumMap<>(Skill.class);

	private boolean sessionStarted;
	private boolean hasState;
	private long sessionCreditsEarned;

	@Inject
	public CreditsTracker(Client client, TcgStateReader tcgStateReader)
	{
		this.client = client;
		this.tcgStateReader = tcgStateReader;
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		sessionStarted = false;
		sessionCarryBySkill.clear();
		sessionSkillXpBySkill.clear();
		hasState = false;
		sessionCreditsEarned = 0L;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!sessionStarted && SkillXp.isLoaded(client))
		{
			tcgStateReader.getState().ifPresent(this::startSession);
		}

		refreshSessionCredits();
	}

	private void refreshSessionCredits()
	{
		hasState = tcgStateReader.getState().isPresent();
		sessionCreditsEarned = hasState && sessionStarted ? creditsSinceSessionStart() : 0L;
	}

	private void startSession(TcgState saved)
	{
		for (Skill skill : Skill.values())
		{
			long currentSkillXp = client.getSkillExperience(skill);
			sessionSkillXpBySkill.put(skill, currentSkillXp);

			CreditRule rule = CreditRule.forSkill(skill);
			if (!rule.earnsCredits())
			{
				continue;
			}

			sessionCarryBySkill.put(skill, sessionCarry(saved, skill, currentSkillXp, rule));
		}

		sessionStarted = true;
	}

	private static long sessionCarry(TcgState saved, Skill skill, long currentSkillXp, CreditRule rule)
	{
		if (!saved.hasBaselineXp(skill))
		{
			return 0L;
		}

		return XpBlocks.xpIntoBlock(
			saved.getUncreditedXp(skill),
			saved.getBaselineXp(skill),
			currentSkillXp,
			rule.getXpPerBlock());
	}

	public boolean hasState()
	{
		return hasState;
	}

	public long getSessionCreditsEarned()
	{
		return sessionCreditsEarned;
	}

	private long creditsSinceSessionStart()
	{
		long credits = 0L;
		for (Map.Entry<Skill, Long> entry : sessionSkillXpBySkill.entrySet())
		{
			Skill skill = entry.getKey();
			long currentSkillXp = client.getSkillExperience(skill);
			credits += LevelUpCredits.between(entry.getValue(), currentSkillXp);

			CreditRule rule = CreditRule.forSkill(skill);
			if (!rule.earnsCredits())
			{
				continue;
			}

			credits += (long) rule.getCreditsPerBlock() * XpBlocks.blocksCompleted(
				sessionCarryBySkill.get(skill),
				entry.getValue(),
				currentSkillXp,
				rule.getXpPerBlock());
		}

		return credits;
	}
}

package com.tcgsessionoverlay.session;

import net.runelite.api.Experience;

public final class LevelUpCredits
{
	static final int FLOOR = 1250;
	static final int CAP = 25000;
	private static final int PROGRESS_LEVELS = 97;
	private static final double CURVE_STEEPNESS = 2.5d;

	private LevelUpCredits()
	{
	}

	public static int forLevel(int level)
	{
		int clamped = clampLevel(level);
		if (clamped <= 2)
		{
			return FLOOR;
		}

		if (clamped >= Experience.MAX_REAL_LEVEL)
		{
			return CAP;
		}

		double progress = (clamped - 2.0d) / PROGRESS_LEVELS;
		double curve = Math.pow(progress, CURVE_STEEPNESS);
		double multiplier = Math.pow((double) CAP / FLOOR, curve);
		return (int) Math.round(FLOOR * multiplier);
	}

	public static long between(long fromSkillXp, long toSkillXp)
	{
		int fromLevel = levelForXp(fromSkillXp);
		int toLevel = levelForXp(toSkillXp);

		long total = 0L;
		for (int level = fromLevel + 1; level <= toLevel; level++)
		{
			total += forLevel(level);
		}

		return total;
	}

	static int levelForXp(long skillXp)
	{
		long bounded = Math.max(0L, Math.min(skillXp, Experience.MAX_SKILL_XP));
		return Experience.getLevelForXp((int) bounded);
	}

	private static int clampLevel(int level)
	{
		return level < 1 ? 1 : Math.min(level, Experience.MAX_VIRT_LEVEL);
	}
}

