import java.time.Duration;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class RatesTracker
{
	static final Duration MINIMUM_ACTIVE_TIME = Duration.ofSeconds(60);
	private static final long MILLIS_PER_HOUR = Duration.ofHours(1).toMillis();

	private final CreditsTracker creditsTracker;
	private final SessionClock sessionClock;

	@Inject
	public RatesTracker(CreditsTracker creditsTracker, SessionClock sessionClock)
	{
		this.creditsTracker = creditsTracker;
		this.sessionClock = sessionClock;
	}

	public long getCreditsPerHour()
	{
		return perHour(creditsTracker.getSessionCreditsEarned(), sessionClock.getActiveTime());
	}

	static long perHour(long amount, Duration activeTime)
	{
		if (activeTime.compareTo(MINIMUM_ACTIVE_TIME) < 0)
		{
			return -1L;
		}

		return amount * MILLIS_PER_HOUR / activeTime.toMillis();
	}
}

package com.tcgsessionoverlay.session;

import java.time.Duration;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

@Singleton
public class SessionClock
{
	static final Duration IDLE_THRESHOLD = Duration.ofMinutes(5);

	private final Map<Skill, Integer> lastKnownXp = new EnumMap<>(Skill.class);

	private boolean hasRecordedGain;
	private long activeNanos;
	private long lastGainAtNanos;

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		lastKnownXp.clear();
		hasRecordedGain = false;
		activeNanos = 0;
		lastGainAtNanos = 0;
	}

	@Subscribe
	public void onStatChanged(StatChanged statChanged)
	{
		Skill skill = statChanged.getSkill();
		int currentXp = statChanged.getXp();
		Integer previousXp = lastKnownXp.put(skill, currentXp);

		if (previousXp != null && currentXp > previousXp)
		{
			recordGain(System.nanoTime());
		}
	}

	void recordGain(long nowNanos)
	{
		if (hasRecordedGain)
		{
			activeNanos += activeGap(lastGainAtNanos, nowNanos);
		}

		hasRecordedGain = true;
		lastGainAtNanos = nowNanos;
	}

	static long activeGap(long fromNanos, long toNanos)
	{
		long gap = toNanos - fromNanos;
		return gap > 0 && gap <= IDLE_THRESHOLD.toNanos() ? gap : 0L;
	}

	public boolean isIdle()
	{
		return hasRecordedGain && System.nanoTime() - lastGainAtNanos > IDLE_THRESHOLD.toNanos();
	}

	public Duration getActiveTime()
	{
		return Duration.ofNanos(activeNanos);
	}
}

