	{
		assertTrue(parser.parse(SAMPLE).isPresent());
	}

	@Test
	public void parsesSaveTime()
	{
		TcgState state = parser.parse(SAMPLE).orElseThrow(AssertionError::new);

		assertEquals(1788382179L, state.getProfileSavedAtUnix());
